contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry performing the property check
    // Parameters mirror sellShares: shareAmount, recipient, mins, data, deadline
    function run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes calldata data, uint256 deadline) public payable {
        require(to != address(0));

        // Observe public state before the call
        uint256 totalSupplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        (uint256 baseReserveBefore, uint256 quoteReserveBefore) = c.getVaultReserve(); if (__ESBMC_reverted()) return;
        uint256 baseInputBefore = c.getBaseInput(); if (__ESBMC_reverted()) return;
        uint256 quoteInputBefore = c.getQuoteInput(); if (__ESBMC_reverted()) return;

        // Perform the call and catch whether it reverted
        bool reverted;
        uint256 baseAmountReturned;
        uint256 quoteAmountReturned;
        (uint256 b, uint256 q) = c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
            baseAmountReturned = b;
            quoteAmountReturned = q;
        }

        // Observe public state after the call
        uint256 totalSupplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        (uint256 baseReserveAfter, uint256 quoteReserveAfter) = c.getVaultReserve(); if (__ESBMC_reverted()) return;
        uint256 baseInputAfter = c.getBaseInput(); if (__ESBMC_reverted()) return;
        uint256 quoteInputAfter = c.getQuoteInput(); if (__ESBMC_reverted()) return;

        // General invariant to assert:
        // If call reverted then public observable reserves and totalSupply must be unchanged.
        // If call succeeded then totalSupply decreased by shareAmount (or by exactly the minted/burnt logic),
        // and vault reserves (as observed by getVaultReserve) decreased by at most the returned base/quote amounts
        // (i.e., after = before - returned OR equal if zero). To keep a single general assert we combine:
        // reverted ==> (after == before for all observed); !reverted ==> totalSupplyAfter <= totalSupplyBefore &&
        // baseReserveAfter + quoteReserveAfter + totalSupplyAfter <= baseReserveBefore + quoteReserveBefore + totalSupplyBefore

        // Build the combined condition
        bool noChangeOnRevert = reverted && (totalSupplyAfter == totalSupplyBefore) && (baseReserveAfter == baseReserveBefore) && (quoteReserveAfter == quoteReserveBefore) && (baseInputAfter == baseInputBefore) && (quoteInputAfter == quoteInputBefore);

        // When not reverted, ensure the combined measure (reserves + totalSupply) did not increase.
        // This is a general conservation-like property: sellShares should not increase the sum of supply + vault reserves.
        uint256 sumBefore = totalSupplyBefore + baseReserveBefore + quoteReserveBefore;
        uint256 sumAfter = totalSupplyAfter + baseReserveAfter + quoteReserveAfter;
        bool nonIncreaseOnSuccess = (!reverted) && (sumAfter <= sumBefore);

        assert(noChangeOnRevert || nonIncreaseOnSuccess);
    }

    // allow receiving ETH in case token transfers use native coin in testing environments
    receive() external payable {}
}

