pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes memory data, uint256 deadline) internal {
        vm.assume(to != address(0));
        uint256 totalSupplyBefore;
        try c.totalSupply() returns (uint256 __r) { totalSupplyBefore = __r; } catch { return; }
        uint256 baseReserveBefore;
        uint256 quoteReserveBefore;
        try c.getVaultReserve() returns (uint256 __r0, uint256 __r1) { baseReserveBefore = __r0; quoteReserveBefore = __r1; } catch { return; }
        uint256 baseInputBefore;
        try c.getBaseInput() returns (uint256 __r) { baseInputBefore = __r; } catch { return; }
        uint256 quoteInputBefore;
        try c.getQuoteInput() returns (uint256 __r) { quoteInputBefore = __r; } catch { return; }
        bool reverted;
        uint256 baseAmountReturned;
        uint256 quoteAmountReturned;
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline) returns (uint256 b, uint256 q) {
            reverted = false;
            baseAmountReturned = b;
            quoteAmountReturned = q;
        } catch {
            reverted = true;
        }
        uint256 totalSupplyAfter;
        try c.totalSupply() returns (uint256 __r) { totalSupplyAfter = __r; } catch { return; }
        uint256 baseReserveAfter;
        uint256 quoteReserveAfter;
        try c.getVaultReserve() returns (uint256 __r0, uint256 __r1) { baseReserveAfter = __r0; quoteReserveAfter = __r1; } catch { return; }
        uint256 baseInputAfter;
        try c.getBaseInput() returns (uint256 __r) { baseInputAfter = __r; } catch { return; }
        uint256 quoteInputAfter;
        try c.getQuoteInput() returns (uint256 __r) { quoteInputAfter = __r; } catch { return; }
        bool noChangeOnRevert = reverted && (totalSupplyAfter == totalSupplyBefore) && (baseReserveAfter == baseReserveBefore) && (quoteReserveAfter == quoteReserveBefore) && (baseInputAfter == baseInputBefore) && (quoteInputAfter == quoteInputBefore);
        uint256 sumBefore = totalSupplyBefore + baseReserveBefore + quoteReserveBefore;
        uint256 sumAfter = totalSupplyAfter + baseReserveAfter + quoteReserveAfter;
        bool nonIncreaseOnSuccess = (!reverted) && (sumAfter <= sumBefore);
        assertTrue(noChangeOnRevert || nonIncreaseOnSuccess);
    }

    function testFuzz_run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, bytes memory data, uint256 deadline) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline);
    }

    receive() external payable {}
}
